ALTER TABLE `cms_content`
    MODIFY COLUMN `content_details` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '文章内容' AFTER `category_id`,
    MODIFY COLUMN `content_title` varchar (255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '文章标题' AFTER `content_details`,
    CHARACTER SET = utf8mb4, COLLATE = utf8mb4_general_ci;

UPDATE `model` SET `model_id` = 1818, `model_parent_ids` = '84,1818', `model_code` = NULL, `model_title` = '查看', `model_url` = 'basic:system:view', `model_icon` = NULL, `model_sort` = 0, `model_ismenu` = 0, `IS_CHILD` = NULL, `model_datetime` = '2024-02-01 16:33:10', `UPDATE_BY` = NULL, `UPDATE_DATE` = NULL, `CREATE_BY` = NULL, `CREATE_DATE` = NULL, `DEL` = 0, `APP_ID` = NULL WHERE `id` = 1819;

UPDATE `mdiy_tag` SET `tag_name` = 'channel', `tag_type` = 'list', `tag_sql` = '<#assign _typeid=\'0\'/>\r\n<#if column?? && column.id?has_content>\r\n    <#assign  _typeid=\'column_id\'>\r\n</#if>\r\n\r\n<#if typeid?has_content>\r\n    <#assign  _typeid=\'typeid\'>\r\n</#if>\r\n<#if typeids??>\r\n    <#assign  _typeids=\'${typeids}\'>\r\n</#if>\r\n\r\n<#assign  _order=\'ASC\'>\r\n\r\n<#if !order?has_content>\r\n    <#assign order=\'ASC\'>\r\n</#if>\r\n\r\n\r\n<#assign  _orderby = \'\'>\r\n\r\n<#if orderby?has_content >\r\n    <#-- 将 orderBy 和 order 拆分为 list -->\r\n    <#assign fields = orderby?split(\',\')>\r\n    <#assign orders = order?split(\',\')>\r\n\r\n    <#-- 遍历所有字段 -->\r\n    <#list 0..(fields?size - 1) as i>\r\n        <#assign field = fields[i]?trim>\r\n        <#-- 如果字段为空则跳过 -->\r\n        <#if !field?has_content>\r\n            <#continue>\r\n        </#if>\r\n\r\n        <#-- 获取对应的排序方向，默认使用 default_order -->\r\n        <#if orders[i]?? && orders[i]?has_content>\r\n            <#assign direction = orders[i]?upper_case>\r\n            <#-- 合法性校验 -->\r\n            <#if direction != \'ASC\' && direction != \'DESC\'>\r\n                <#assign direction = _order>\r\n            </#if>\r\n        <#else>\r\n            <#assign direction = _order>\r\n        </#if>\r\n\r\n        <#assign ordercolumn = \'\'>\r\n        <#-- 映射字段 -->\r\n        <#if field == \'date\'>\r\n            <#assign ordercolumn = \'cms_category.create_date\'>\r\n        <#elseif field == \'sort\'>\r\n            <#assign ordercolumn = \'cms_category.category_sort\'>\r\n        <#else>\r\n            <#-- 不支持的字段，跳过 -->\r\n            <#continue>\r\n        </#if>\r\n        <#-- 拼接到最终结果 -->\r\n        <#if _orderby?has_content>\r\n            <#assign _orderby += \',\'>\r\n        </#if>\r\n        <#assign _orderby += ordercolumn + \' \' + direction>\r\n    </#list>\r\n     <#-- 容错处理，如果什么都没有匹配到，则默认按栏目id排序 -->\r\n    <#if !_orderby?has_content>\r\n        <#assign _orderby = \'cms_category.id \' + _order>\r\n    </#if>\r\n<#else>\r\n    <#assign _orderby = \'cms_category.id \' + _order>\r\n</#if>\r\n\r\n\r\n\r\nselect\r\n    cms_category.id as \"id\",\r\n    cms_category.id as \"typeid\",\r\n    cms_category.category_title as \"typetitle\",\r\n    cms_category.category_short_title as \"typeshorttitle\",\r\n        <#--动态链接-->\r\n        <#if isDo?? && isDo>\r\n    CASE WHEN cms_category.category_type= \'2\' THEN CONCAT(\'/${modelName}/view.do?style=${templateName!\"\"}&typeid=\', cms_category.id) ELSE CONCAT(\'/${modelName}/list.do?style=${templateName!\"\"}&typeid=\', cms_category.id) END as \"typelink\",\r\n    <#else>\r\n        <#--栏目类型为链接-->\r\n        <#if shortSwitch?? && shortSwitch>\r\n            CONCAT(cms_category.category_pinyin,\'.html\') AS \"typelink\",\r\n        <#else>\r\n            CONCAT(cms_category.category_path,\'/index.html\') as \"typelink\",\r\n        </#if>\r\n    </#if>\r\n    cms_category.category_keyword as \"typekeyword\",\r\n    cms_category.category_diy_url as \"typeurl\",\r\n    cms_category.category_flag as \"flag\",\r\n    cms_category.category_id as \"parentid\",\r\n    cms_category.category_parent_ids as \"parentids\",\r\n    cms_category.category_descrip as \"typedescrip\",\r\n    cms_category.category_type as \"type\",\r\n    cms_category.category_path as \"typepath\",\r\n    cms_category.leaf as \"typeleaf\",\r\n    cms_category.category_img as \"typelitpic\" ,\r\n    cms_category.category_ico as \"typeico\" ,\r\n    <#if tableName??>${tableName}.*,</#if>\r\n( SELECT count(*) FROM cms_category cc WHERE cc.category_id = cms_category.id AND cc.del = 0 ) AS \"childsize\"\r\nfrom\r\ncms_category\r\n<#--判断是否有自定义模型表-->\r\n<#if tableName??>LEFT JOIN ${tableName} ON ${tableName}.link_id=cms_category.id</#if>\r\nwhere\r\ncms_category.del=0\r\nand  cms_category.category_display = \'enable\'\r\nand  cms_category.is_child = \'cms\'\r\n<#--自定义模型-->\r\n<#if diyModel?? && tableName??>\r\n<#list diyModel as key, value>\r\n<#-- 生成占位符名称 -->\r\n<#assign paramName = \"diyModel_\" + key>\r\nand ${tableName}.${key} like CONCAT(CONCAT(\'%\',:${paramName}),\'%\')\r\n</#list>\r\n</#if>\r\n<#--根据站点编号查询-->\r\n<#if appId?? >\r\nand cms_category.app_id=:appId\r\n</#if>\r\n\r\n<#--栏目属性-->\r\n<#if flag?? >\r\n<#assign flagList = flag?split(\',\')>\r\nand\r\n(<#list flagList as item>\r\n<#if item?index gt 0> or</#if>\r\nFIND_IN_SET(<#if flagList?size == 1>:flag<#else>:flag_${item?index}</#if>,cms_category.category_flag)>0\r\n</#list>)\r\n</#if>\r\n\r\n<#if noflag?? && noflag?has_content>\r\n<#assign noflagList = noflag?split(\',\')>\r\nand (\r\n<#list noflagList as item>\r\n<#if item?index gt 0>and </#if>\r\nFIND_IN_SET(\r\n<#if noflagList?size == 1>:noflag<#else>:noflag_${item?index}</#if>,\r\ncms_category.category_flag\r\n) = 0\r\n</#list>\r\nor cms_category.category_flag is null)\r\n</#if>\r\n\r\n<#--type-->\r\n<#if !type??||!type?has_content>\r\n<#assign type=\'\'/>\r\n</#if>\r\n\r\n<#-- 如果有typeids参数，则只查询typeids参数指定的栏目  -->\r\n<#if _typeids?has_content>\r\nand cms_category.id in (:typeids) <#-- 预编译处理，后端需传入List -->\r\n<#elseif type?has_content>\r\n<#--顶级栏目（单个）-->\r\n<#if type==\'top\'>\r\n<#if _typeid != \'0\'>\r\nand (cms_category.id = cms_category.top_id or cms_category.top_id = \'0\')\r\n</#if>\r\n\r\n<#elseif type==\'nav\'>\r\nand(cms_category.category_id is null)\r\n\r\n<#--同级栏目（多个）-->\r\n<#elseif type==\'level\'>\r\n<#if _typeid != \'0\'>\r\nand cms_category.category_id=(select category_id from cms_category where id=:${_typeid})\r\n</#if>\r\n\r\n<#--当前栏目或指定栏目（单个）-->\r\n<#elseif type==\'self\'>\r\n<#if _typeid != \'0\'>\r\nand cms_category.id=:${_typeid}\r\n</#if>\r\n\r\n\r\n<#--当前栏目的所属栏目（多个）-->\r\n<#elseif type==\'path\'>\r\n<#if _typeid != \'0\'>\r\nand cms_category.id in\r\n(<#if column?? && column.categoryParentIds??>\r\n<#assign parentIdsList = column.categoryParentIds?split(\',\')>\r\n<#list parentIdsList as parentId>\r\n<#if parentIdsList?size == 1>:column_categoryParentIds<#else>:column_categoryParentIds_${parentId?index}</#if>,\r\n</#list>\r\n</#if>:${_typeid})\r\n</#if>\r\n\r\n<#--子栏目（多个）-->\r\n<#elseif type==\'son\'>\r\n<#if _typeid != \'0\'>\r\nand cms_category.category_id=:${_typeid}\r\n</#if>\r\n\r\n<#--上一级栏目没有则取当前栏目（单个）-->\r\n<#elseif type==\'parent\'>\r\nand\r\n<#if typeid?has_content>\r\ncms_category.id=(select category_id from cms_category where id=:${_typeid})\r\n<#else>\r\ncms_category.id=:column_categoryId\r\n</#if>\r\n</#if>\r\n\r\n<#else>\r\n<#--如果没有指定typeid则查询所有，否则查询指定栏目下所有栏目-->\r\n<#if _typeid != \'0\'>\r\nand cms_category.top_id=:${_typeid}\r\n</#if>\r\n</#if>\r\n\r\n<#--字段排序-->\r\n<#if type == \'path\'>\r\nORDER BY cms_category.category_path asc\r\n<#else>\r\n\r\nORDER BY  ${_orderby}\r\n\r\n</#if>\r\n<#if size??>\r\nLIMIT ${size}\r\n</#if>', `tag_class` = NULL, `tag_description` = '通用栏目', `MODEL_ID` = NULL, `UPDATE_BY` = NULL, `UPDATE_DATE` = NULL, `CREATE_BY` = NULL, `CREATE_DATE` = NULL, `APP_ID` = 'global', `DEL` = 0, `NOT_DEL` = 1 WHERE `id` = 4;
